import { test, expect } from '@playwright/test';

test.describe('User Permissions - Edit Content', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display permissions error when editing another user\'s content', async ({ page }) => {
    // Setup: Navigate to user profile page
    await page.getByRole('button', { name: /view user/i }).click();
    const userProfilePage = page.getByRole('region', { name: /user profile/i });
    await expect(userProfilePage).toBeVisible();

    // Intercept API call to get user details
    await page.route('**/api/users/12345/details', (route) => {
      route.abort('failed');
    });

    // Verify error message is visible
    const errorMessage = page.getByText(/permission denied/i);
    await expect(errorMessage).toBeVisible();

    // Verify edit button is disabled
    const editButton = page.getByRole('button', { name: /edit content/i });
    await expect(editButton).toBeDisabled();

    // Verify error icon is visible
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();

    // Verify user profile details are not displayed
    await expect(userProfilePage).not.toBeVisible();
  });

  test('should allow editing own content without permission error', async ({ page }) => {
    // Setup: Navigate to user profile page
    await page.getByRole('button', { name: /view user/i }).click();
    const userProfilePage = page.getByRole('region', { name: /user profile/i });
    await expect(userProfilePage).toBeVisible();

    // Intercept API call to get user details
    await page.route('**/api/users/12345/details', (route) => {
      route.continue();
    });

    // Verify user details are displayed
    const userName = page.getByText(/John Doe/i);
    await expect(userName).toBeVisible();

    // Verify edit button is enabled
    const editButton = page.getByRole('button', { name: /edit content/i });
    await expect(editButton).toBeEnabled();

    // Verify edit button is visible
    await expect(editButton).toBeVisible();

    // Verify edit button is clickable
    await expect(editButton).toBeClickable();

    // Verify edit form is visible
    const editForm = page.getByRole('form', { name: /edit content/i });
    await expect(editForm).toBeVisible();

    // Verify form fields are present
    const titleInput = page.getByLabel(/title/i);
    await expect(titleInput).toBeVisible();

    const contentInput = page.getByLabel(/content/i);
    await expect(contentInput).toBeVisible();

    // Verify save button is visible
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();

    // Verify save button is clickable
    await expect(saveButton).toBeClickable();

    // Verify success message appears
    const successMessage = page.getByText(/content saved successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify edit button is now disabled
    await expect(editButton).toBeDisabled();
  });
});
